{
  "name": "@amykit/plugin-agent-relay",
  "version": "0.6.0",
  "description": "One agent made of several: swaps harness on a quota, escalates model on a failure.",
  "type": "module",
  "license": "MIT",
  "author": "Nicolas Melo",
  "homepage": "https://github.com/nicolasmelo1/amy#readme",
  "bugs": "https://github.com/nicolasmelo1/amy/issues",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/nicolasmelo1/amy.git",
    "directory": "plugins/agent-relay"
  },
  "publishConfig": {
    "access": "public",
    "registry": "https://registry.npmjs.org"
  },
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    }
  },
  "files": [
    "dist"
  ],
  "dependencies": {
    "@amykit/agent-kit": "^0.6.0",
    "@amykit/core": "^0.6.0",
    "@amykit/model-specs": "^0.6.0"
  },
  "devDependencies": {
    "@amykit/test-fixtures": "^0.1.0"
  }
}

import { ConfigSchema } from "@amykit/core";

/** What this plugin needs told to it, and nothing more. */
export const configSchema = {
  ladder: {
    type: "string[]",
    description:
      "the contributed agents to try, in order, such as [claude:sonnet, claude:opus, codex:gpt-5]. Empty means every contributed agent, in the order the plugins were mounted",
    default: [],
  },
  ladderByStep: {
    type: "record",
    description:
      "a ladder for one step, overriding the one above, keyed by the workflow's action name: {\"triage\": [\"claude:haiku\"], \"implement\": [\"claude:opus\"]}. Reading a ticket and writing the change are not the same job, and one list for both means paying the expensive model to do the cheap step",
    default: {},
  },
  skills: {
    type: "record",
    description:
      "which skills answer for a step, in the order they are tried, keyed by the workflow's action name: {\"triage\": [\"/logion\"]}. A skill named here must be installed, or the mount is refused",
    default: {},
  },
  skillRoots: {
    type: "string[]",
    description:
      "where installed skills are looked for. Empty means ~/.claude/skills, which is where the harness looks",
    default: [],
  },
  budget: {
    type: "record",
    description:
      "what the agents may spend, per window: perFiveHours and perWeek, each with tokens and/or costUsd, plus stopAt, the fraction of a ceiling at which new work stops being started",
    default: {},
  },
} satisfies ConfigSchema;

export { configSchema } from "./config.js";
export { capsMoney, inertCeilingProblems, unpricedRungs } from "./pricing.js";
export type { UnpricedRung } from "./pricing.js";
export { DEFAULT_SKILL_ROOT, installedSkills, locateSkill, parseSkills, skillsNamed } from "./skills.js";
export type { SkillsResult } from "./skills.js";
export { plugin } from "./plugin.js";

import fs from "node:fs";
import path from "node:path";
import {
  Agent,
  AskContext,
  HarnessReply,
  CommandOutput,
  LogBudget,
  PluginCommand,
  definePlugin,
  PluginContext,
  Registry,
  deferred,
  hasACeiling,
  parseBudget,
  ConfigOf,
} from "@amykit/core";
import { MODELS_DEV_URL, ModelsDevCatalog, OVERRIDE_FILE, SpecTable, forgetSpecTable, refreshFrom, specTable } from "@amykit/model-specs";
import { HARNESS_COLLECTION, HarnessRelay, NamedHarness, Ladders, Rung, SkillLadders } from "@amykit/agent-kit";
import { configSchema } from "./config.js";

type TypedContext = PluginContext<ConfigOf<typeof configSchema>>;
import { inertCeilingProblems } from "./pricing.js";
import { DEFAULT_SKILL_ROOT, installedSkills, locateSkill, parseSkills, skillsNamed } from "./skills.js";

type Settings = ConfigOf<typeof configSchema>;

/**
 * What each model is believed to cost.
 *
 * Here rather than in the host because the price table is the business of the
 * one thing that spends an agent: a machine with no relay has nothing to
 * price, and a price list that came with the CLI was a fact about a package
 * rather than about this install.
 */
const models: PluginCommand<Settings> = {
  name: "models",
  description: "What each model is believed to cost",
  subcommands: [
    {
      name: "show",
      description: "The price table in force",
      default: true,
      run({ home, out }) {
        const table = specTable(home);
        out.line(`source: ${table.source}`);
        out.line();
        for (const spec of table.models) {
          const tier = spec.thresholdTokens
            ? `  (above ${spec.thresholdTokens.toLocaleString()} input tokens every rate changes)`
            : "";
          out.line(
            `  ${spec.model.padEnd(22)} in ${perMillion(spec.inputPerToken)}  ` +
              `out ${perMillion(spec.outputPerToken)}  ` +
              `cache r/w ${perMillion(spec.cacheReadPerToken)}/${perMillion(spec.cacheWritePerToken)}${tier}`,
          );
        }
        out.line();
        out.line(table.note);
      },
    },
    {
      name: "refresh",
      description: "Take the base rates from models.dev, keeping what it does not carry",
      flags: [
        { flags: "--dry-run", description: "say what would change and write nothing" },
        { flags: "--stale-after <days>", description: "refresh only a table written more than this many days ago" },
      ],
      async run({ home, options, out }) {
        const staleAfter = options.staleAfter === undefined ? undefined : Number(options.staleAfter);
        if (staleAfter !== undefined && !isStale(home, staleAfter)) {
          out.line(`the price table is younger than ${staleAfter} day(s); nothing to refresh`);
          return;
        }

        const table = await refreshed(home, out);
        if (!table || options.dryRun === true) return;

        const file = path.join(home, OVERRIDE_FILE);
        fs.mkdirSync(path.dirname(file), { recursive: true });
        fs.writeFileSync(file, `${JSON.stringify(table, null, 2)}\n`, "utf-8");
        forgetSpecTable();
        out.line(`\nwrote ${file}`);
        out.line("Long-context tiering was kept: models.dev does not publish it.");
      },
    },
  ],
};

/** Whether the table on this machine is older than a number of days. */
function isStale(home: string, days: number): boolean {
  try {
    return Date.now() - fs.statSync(path.join(home, OVERRIDE_FILE)).mtimeMs > days * 86_400_000;
  } catch {
    // No table written yet: the vendored one arrived with the release, and
    // there is no honest way to say when that was.
    return true;
  }
}

/**
 * Fetches and compares, and writes nothing.
 *
 * A refresh that cannot reach models.dev leaves the table exactly as it was:
 * the next agent call paying for yesterday's price is a smaller problem than
 * a table emptied because a network call failed.
 */
async function refreshed(home: string, out: Pick<CommandOutput, "line" | "error">): Promise<SpecTable | undefined> {
  try {
    // Bounded, because this runs on a start and an update: a price list is
    // not worth holding a loop up for, and a machine with no route out must
    // come back to the table it already had rather than wait.
    const response = await fetch(MODELS_DEV_URL, { signal: AbortSignal.timeout(5_000) });
    if (!response.ok) {
      out.error(`${MODELS_DEV_URL} answered ${response.status}`);
      process.exitCode = 1;
      return undefined;
    }

    const report = refreshFrom((await response.json()) as ModelsDevCatalog, specTable(home));
    if (report.changed.length === 0) out.line("nothing changed");
    for (const change of report.changed) {
      out.line(`  ${change.model} ${change.field}: ${perMillion(change.was)} -> ${perMillion(change.now)}`);
    }
    for (const model of report.unmatched) {
      out.line(`  ${model}: models.dev does not know it, left as it was`);
    }
    return report.table;
  } catch (error) {
    out.error(`the price table was left as it was: ${error instanceof Error ? error.message : String(error)}`);
    process.exitCode = 1;
    return undefined;
  }
}

/** Dollars per million tokens, which is how a price list is written. */
function perMillion(perToken: number | undefined): string {
  if (perToken === undefined) return "—";
  const dollars = perToken * 1_000_000;
  const decimals = Number.isInteger(dollars * 100) ? 2 : 4;
  return `$${dollars.toFixed(decimals)}`;
}

export const plugin = definePlugin<typeof configSchema>({
  name: "@amykit/plugin-agent-relay",
  configSchema,
  commands: [models],
  register(registry, ctx) {
    // Deferred: the harnesses it relays to are contributed by plugins that
    // may be listed after this one. The host builds it once every plugin has
    // registered, so a ladder naming an agent nobody contributed is a typo
    // that costs a boot rather than somebody's ticket.
    //
    // The port is `ask` and nothing else. Every workflow's steps go up the
    // same ladder, into the same log and under the same ceiling, keyed by the
    // step each one names in its context.
    registry.port("agent", deferred(() => {
      const relay = build(ctx);
      const agent: Agent & { name: string } = {
        ask: (prompt: string, cwd: string, context?: AskContext): Promise<HarnessReply> =>
          relay.ask(prompt, cwd, context),
        name: "relay",
      };
      return agent;
    }));
    mountBudget(registry, ctx);
  },
});

/**
 * Mounts the ceiling the engine asks before it starts anything expensive.
 *
 * It belongs to this plugin because this is the only thing in the system
 * that spends an agent, and it is only mounted when a ceiling was actually
 * configured: a budget that can never refuse is a port pretending to be one.
 */
function mountBudget(registry: Registry, ctx: TypedContext): void {
  const parsed = parseBudget(ctx.config.budget);
  if (!parsed.ok) throw new Error(parsed.problems.join("; "));

  if (!hasACeiling(parsed.limits)) return;

  if (!ctx.log) {
    throw new Error(
      "`budget` sets a ceiling, and the host mounted no event log to measure the spending against",
    );
  }

  registry.port("budget", new LogBudget(ctx.log, parsed.limits));
}

function build(ctx: TypedContext): HarnessRelay {
  const contributed = [...ctx.contributions(HARNESS_COLLECTION).values()] as NamedHarness[];
  const rungs = ladders(ctx, contributed);

  // Here rather than beside `mountBudget`, because this is the one question
  // that needs both halves in hand: what the ceiling is measured in, and
  // which models are underneath it. `register` has only the first.
  refuseAnInertCeiling(ctx, rungs);

  return new HarnessRelay(rungs, {
    log: ctx.log,
    now: ctx.now,
    skills: skillLadders(ctx),
    locate: (skill) => locateSkill(skillRootsOf(ctx), skill),
  });
}

/**
 * Refuses a ceiling in money over a ladder whose cost nobody could work out.
 *
 * The other half of the sentence `mountBudget` already says. That one refuses
 * a budget naming a window nobody meters; this one refuses a budget naming a
 * measure nobody can supply, which is the same failure — a ceiling that reads
 * like policy and is decoration — arrived at from the other side.
 */
function refuseAnInertCeiling(ctx: TypedContext, rungs: Ladders<NamedHarness>): void {
  const parsed = parseBudget(ctx.config.budget);
  if (!parsed.ok) throw new Error(parsed.problems.join("; "));

  const problems = inertCeilingProblems(parsed.limits, rungs);
  if (problems.length > 0) throw new Error(problems.join("; "));
}

/**
 * The ladders the config asked for: one fallback, and one per named step.
 *
 * Every name is resolved against what was contributed, including the ones
 * inside a step's ladder, so a typo in `ladderByStep` is refused at boot with
 * the same message a typo in `ladder` gets. A step ladder that quietly meant
 * less than it said would show up as one action mysteriously using the wrong
 * model, which is the hardest kind of thing to notice.
 */
function ladders<T extends Rung>(ctx: TypedContext, contributed: readonly T[]): Ladders<T> {
  const wanted = ctx.config.ladder;
  const fallback = wanted.length === 0 ? [...contributed] : order(contributed, wanted);

  const perStep = ctx.config.ladderByStep as Record<string, unknown>;
  const byStep: Record<string, readonly T[]> = {};

  for (const [step, names] of Object.entries(perStep)) {
    if (!Array.isArray(names) || names.some((name) => typeof name !== "string")) {
      throw new Error(`\`ladderByStep.${step}\` must be a list of contributed agent names`);
    }
    if (names.length === 0) continue;

    byStep[step] = order(contributed, names);
  }

  return { fallback, byStep };
}

/**
 * The skill ladders, with every name checked against what is installed.
 *
 * Refused at boot rather than skipped, for the same reason a ladder naming an
 * agent nobody contributed is refused: a config that quietly means less than
 * it says is worse than one that will not load.
 */
function skillLadders(ctx: TypedContext): SkillLadders {
  const parsed = parseSkills(ctx.config.skills);
  if (!parsed.ok) throw new Error(parsed.problems.join("; "));

  const installed = installedSkills(skillRootsOf(ctx));

  const missing = skillsNamed(parsed.ladders).filter((skill) => !installed.includes(skill));
  if (missing.length > 0) {
    throw new Error(
      `skills name \`${missing.map((name) => `/${name}`).join(", ")}\`, which is not installed. ` +
        `Installed: ${installed.map((name) => `/${name}`).join(", ") || "nothing"}`,
    );
  }

  return parsed.ladders;
}

/** Where installed skills are looked for: the configured roots, or the harness's own. */
function skillRootsOf(ctx: TypedContext): readonly string[] {
  const roots = ctx.config.skillRoots;
  return roots.length > 0 ? roots : [DEFAULT_SKILL_ROOT];
}

/**
 * The ladder the config asked for, in that order.
 *
 * A name nobody contributed is refused rather than skipped: a ladder with a
 * typo in it would quietly become shorter than the operator believes, and the
 * first symptom would be a ticket escalating for no reason.
 */
function order<T extends Rung>(contributed: readonly T[], wanted: readonly string[]): T[] {
  return wanted.map((name) => {
    const found = contributed.find((agent) => agent.name === name);
    if (!found) {
      throw new Error(
        `the ladder names \`${name}\`, which no harness contributed. ` +
          `Contributed: ${contributed.map((a) => a.name).join(", ") || "nothing"}`,
      );
    }
    return found;
  });
}

import { BUDGET_WINDOWS, BudgetLimits, ceilingFor } from "@amykit/core";
import { Ladders, Rung, everyRung } from "@amykit/agent-kit";
import { SpecTable, aliasFor, specFor, specTable } from "@amykit/model-specs";

/** A rung the price table has nothing to say about. */
export interface UnpricedRung {
  /** The ladder entry, as the config wrote it: `claude:sonnet`. */
  readonly rung: string;
  /** The model that entry names, or empty when it named none. */
  readonly model: string;
}

/** Whether any window caps money, which is the only ceiling a price can break. */
export function capsMoney(limits: BudgetLimits): boolean {
  return BUDGET_WINDOWS.some((window) => ceilingFor(limits, window.name)?.costUsd !== undefined);
}

/**
 * The rungs no price table entry covers, in ladder order and named once each.
 *
 * Every step's ladder, not just the default: a model named only under
 * `ladderByStep.implement` is the model that does the expensive half of the
 * work, and it is the one whose cost going missing matters most.
 */
export function unpricedRungs<T extends Rung>(
  ladders: Ladders<T>,
  table: SpecTable = specTable(),
): UnpricedRung[] {
  const found: UnpricedRung[] = [];
  const seen = new Set<string>();

  for (const rung of everyRung(ladders)) {
    if (seen.has(rung.name)) continue;
    seen.add(rung.name);

    // The harness accounts for itself, so the table is a backstop it may
    // never reach and a missing row costs the ceiling nothing. Asked before
    // the table, because for these two the table's answer is not the
    // question: claude reports `total_cost_usd`, and a hermes run on a local
    // model is `included` at zero, which no price list will ever carry.
    if (rung.pricesItsOwnRuns) continue;

    if (specFor(aliasFor(rung.model, table), table)) continue;
    found.push({ rung: rung.name, model: rung.model });
  }

  return found;
}

/**
 * Why a dollar ceiling over this ladder could not stop anything, or nothing.
 *
 * A ceiling in `costUsd` is only a ceiling if the runs underneath it arrive
 * with a price on them. When the table cannot price a rung, that rung's runs
 * are recorded with no `costUsd`, the dollar figure never moves, and the
 * ceiling written in the config is not loose — it is inert. The token ceiling
 * beside it still fires, which is what makes it quiet: the machine does stop
 * sometimes, just never for the reason that was written down.
 *
 * So it is refused where a typo in a ladder is refused, and for the same
 * reason: while boot can still refuse, rather than three weeks later when
 * somebody reads the bill.
 *
 * Pure, and told the table rather than reading it, so a test can hand it a
 * table with a hole in a known place.
 */
export function inertCeilingProblems<T extends Rung>(
  limits: BudgetLimits,
  ladders: Ladders<T>,
  table: SpecTable = specTable(),
): string[] {
  // A ceiling in tokens needs no price table at all. Tokens are what a
  // subscription meters, they are reported by every harness that runs, and an
  // install that wants a ceiling without one of these arguments has it.
  if (!capsMoney(limits)) return [];

  const unpriced = unpricedRungs(ladders, table);
  if (unpriced.length === 0) return [];

  return unpriced.map(
    ({ rung, model }) =>
      `\`budget\` sets a costUsd ceiling, and ${named(model)} — which the rung \`${rung}\` ` +
      "names — is not in the price table, and this harness reports no cost of its own, so " +
      "runs on it would be recorded with no cost and that ceiling could never stop " +
      "anything. `amy models refresh` re-rates the models the table already has and never " +
      "adds one, so give it a row in `.amy/model-specs.json`, or set the ceiling in tokens.",
  );
}

/** `\`opus-6\``, or a phrase for a rung that named no model to price. */
function named(model: string): string {
  return model ? `\`${model}\`` : "the harness default model, which has no id to price";
}

import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { CORE_ACTIONS, dispatchesTo } from "@amykit/core";
import { SkillLadders } from "@amykit/agent-kit";

export type SkillsResult =
  | { ok: true; ladders: SkillLadders }
  | { ok: false; problems: string[] };

/** Where a Claude Code skill is installed, unless the config says otherwise. */
export const DEFAULT_SKILL_ROOT = "~/.claude/skills";

/**
 * Reads the `skills` setting: a ladder of skills per step.
 *
 * The keys are the workflow's own action names rather than a second
 * vocabulary, and only the ones that reach an agent can be handed to a skill.
 * A step nobody dispatches to an agent is a typo, and it is cheaper to say so
 * at boot than to leave a ladder that never fires.
 */
export function parseSkills(value: unknown): SkillsResult {
  if (value === undefined) return { ok: true, ladders: {} };
  if (!isRecord(value)) return { ok: false, problems: ["`skills` must be a mapping of step to skills"] };

  const problems: string[] = [];
  const ladders: Record<string, string[]> = {};

  for (const [step, named] of Object.entries(value)) {
    if (!dispatchesTo(step, "agent")) {
      problems.push(`\`skills.${step}\` is not a step an agent performs: ${agentSteps().join(", ")}`);
      continue;
    }

    const ladder = ladderIn(step, named, problems);
    if (ladder) ladders[step] = ladder;
  }

  return problems.length > 0 ? { ok: false, problems } : { ok: true, ladders };
}

/** Every skill named across every step, once each. */
export function skillsNamed(ladders: SkillLadders): string[] {
  return [...new Set(Object.values(ladders).flat())];
}

/**
 * The skills installed on this machine, by name.
 *
 * A directory holding a `SKILL.md` is what "installed" means, which is the
 * same thing the harness itself looks for. Asking the filesystem rather than
 * the harness keeps this answerable at boot, before anything is run.
 */
export function installedSkills(roots: readonly string[]): string[] {
  const found = roots.flatMap((root) => skillsUnder(expandHome(root)));
  return [...new Set(found)].sort();
}

/**
 * The directory a skill is installed in, from the first root that holds it.
 *
 * The same roots, in the same order, `installedSkills` answered from, so a
 * skill the mount accepted is a skill this finds.
 */
export function locateSkill(roots: readonly string[], skill: string): string | undefined {
  for (const root of roots) {
    const directory = path.join(expandHome(root), skill);
    if (fs.existsSync(path.join(directory, "SKILL.md"))) return directory;
  }
  return undefined;
}

function skillsUnder(root: string): string[] {
  if (!fs.existsSync(root)) return [];

  return fs
    .readdirSync(root, { withFileTypes: true })
    .filter((entry) => entry.isDirectory())
    .filter((entry) => fs.existsSync(path.join(root, entry.name, "SKILL.md")))
    .map((entry) => entry.name);
}

function ladderIn(step: string, named: unknown, problems: string[]): string[] | null {
  if (!Array.isArray(named) || named.some((name) => typeof name !== "string")) {
    problems.push(`\`skills.${step}\` must be a list of skill names, such as [/logion]`);
    return null;
  }

  if (named.length === 0) {
    problems.push(`\`skills.${step}\` names no skill, so it decides nothing`);
    return null;
  }

  // Written with the leading slash, because that is how a skill is invoked
  // and how anyone reading the config will recognise it.
  return (named as string[]).map((name) => name.replace(/^\//, ""));
}

function agentSteps(): string[] {
  return Object.keys(CORE_ACTIONS).filter((action) => dispatchesTo(action, "agent"));
}

function expandHome(value: string): string {
  if (value === "~") return os.homedir();
  return value.startsWith("~/") ? path.join(os.homedir(), value.slice(2)) : value;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}
